const ico=(key,size=18)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[key]||icons.arrow}</svg>`;
const save=()=>{ if(preview) storage.setItem(KEY,JSON.stringify(state)) };
const toast=(msg)=>{document.querySelectorAll('.toast').forEach(e=>e.remove());let n=document.createElement('div');n.className='toast';n.innerHTML=ico('check')+esc(msg);document.body.appendChild(n);setTimeout(()=>n.remove(),3600)};
const image=(p)=>`<img src="${esc(p.image||base+p.backup_image)}" alt="${esc(p.title)}" loading="lazy" onerror="this.onerror=null;this.src='${base}${esc(p.backup_image||'assets/img/architecture-1.svg')}'">`;
const route=(page,id)=>preview?`index.html?page=${page}${id?'&id='+id:''}`:(page==='home'?'/':page==='detail'?'/property/'+id:(page==='insights' && id)?'/insights/'+id:'/'+page);
const adminLink=preview?'dashboard.html':'/admin';
const current=()=>{let q=new URLSearchParams(location.search); if(preview)return {page:q.get('page')||'home',id:q.get('id')};let seg=location.pathname.split('/').filter(Boolean);return {page:seg[0]==='property'?'detail':seg[0]||'home',id:seg[1]}};
const propName=p=>txt(p.title,p.title_ar);
function card(p){return `<article class="property-card" data-property="${p.id}"><a class="pc-image" href="${route('detail',p.id)}" data-nav="detail" data-id="${p.id}">${image(p)}<span class="pc-badge">${p.listing_type==='Sale'?txt('FOR SALE','للبيع'):txt('FOR RENT','للإيجار')}</span><span class="pc-more">${txt('EXPLORE PROPERTY','استكشف العقار')} ${ico('arrow',17)}</span></a><button class="favorite ${favorite.includes(p.id)?'active':''}" data-fav="${p.id}" aria-label="Favorite">${ico('heart',19)}</button><div class="pc-body"><span class="eyebrow small">${ico('pin',13)} ${esc(p.location)}</span><a href="${route('detail',p.id)}" data-nav="detail" data-id="${p.id}" class="pc-title">${esc(propName(p))}</a><div class="pc-price">${money(p.price)} <small>${p.listing_type==='Rent'?txt('/ year','/ سنوياً'):''}</small></div><div class="pc-features"><span>${ico('bed',17)} ${fmt(p.bedrooms)} ${txt('Beds','غرف')}</span><span>${ico('bath',17)} ${fmt(p.bathrooms)} ${txt('Baths','حمامات')}</span><span>${ico('area',16)} ${fmt(p.area_sqft)} ${txt('sq.ft','قدم²')}</span></div><div class="pc-bottom"><button class="link-button" data-detail="${p.id}">${txt('View property','عرض العقار')} ${ico('arrow',16)}</button><label class="compare-label"><input type="checkbox" data-compare="${p.id}" ${compare.includes(p.id)?'checked':''}> ${txt('Compare','مقارنة')}</label></div></div></article>`}
function header(){let page=current().page;return `<div class="topline"><div class="container topflex"><span>${ico('pin',13)} ${txt('A distinguished address in the UAE','عنوان مميز في الإمارات')}</span><span>${txt('Curated real estate experience','تجربة عقارية استثنائية')} <span class="top-dot">✦</span> ${txt('Dubai • Sharjah • UAE','دبي • الشارقة • الإمارات')}</span></div></div><header class="site-header"><div class="container navwrap"><a href="${route('home')}" data-nav="home" class="brand"><span class="brandmark"><img src="${base}assets/img/alhasm-logo.webp" alt="AL HASM Logo"></span><span class="brandwords"><strong>AL HASM<span class="gold">.</span></strong><small>PREMIER PROPERTIES</small></span></a><nav class="main-nav" id="mainnav">${[['home','Home','الرئيسية'],['properties','Properties','العقارات'],['about','About us','من نحن'],['services','Services','خدماتنا'],['insights','Insights','المدونة'],['contact','Contact','تواصل معنا']].map(([n,e,a])=>`<a data-nav="${n}" href="${route(n)}" class="${page===n?'selected':''}">${txt(e,a)}</a>`).join('')}</nav><div class="nav-actions"><button class="nav-minor" id="language" aria-label="Change language">${lang==='en'?'عربي':'EN'}</button><a href="${route('favorites')}" class="nav-heart" data-nav="favorites" title="Favorites">${ico('heart',20)} <span>${favorite.length}</span></a><a href="${route('contact')}" data-nav="contact" class="btn btn-gold nav-cta">${txt('List your property','أضف عقارك')} ${ico('arrow',16)}</a><button class="nav-hamb" id="navmenu" aria-label="Open menu">${ico('menu',23)}</button></div></div></header>`}
function footer(){return `<footer class="footer"><div class="container footer-grid"><div><a href="${route('home')}" data-nav="home" class="brand darkbrand"><span class="brandmark"><img src="${base}assets/img/alhasm-logo.webp" alt=""></span><span class="brandwords"><strong>AL HASM<span class="gold">.</span></strong><small>PREMIER PROPERTIES</small></span></a><p>${txt('The art of exceptional living. Discover carefully selected properties and personalized guidance for every stage of your real estate journey.','فن الحياة الاستثنائية. اكتشف عقارات مختارة بعناية وخدمة شخصية في كل مرحلة من رحلتك العقارية.')}</p></div><div><b>${txt('Explore','استكشف')}</b>${[['properties','Properties','العقارات'],['about','About us','من نحن'],['services','Our services','خدماتنا'],['insights','Journal','المدونة'],['favorites','Saved properties','المفضلة'],['mortgage','Mortgage planner','حاسبة التمويل']].map(x=>`<a href="${route(x[0])}" data-nav="${x[0]}">${txt(x[1],x[2])}</a>`).join('')}</div><div><b>${txt('Our services','خدماتنا')}</b><a href="${route('properties')}" data-nav="properties">${txt('Buy a property','شراء عقار')}</a><a href="${route('properties')}" data-nav="properties">${txt('Rent a property','استئجار عقار')}</a><a href="${route('valuation')}" data-nav="valuation">${txt('Request valuation','طلب تقييم')}</a><a href="${route('mortgage')}" data-nav="mortgage">${txt('Mortgage planner','حاسبة التمويل')}</a><a href="${route('contact')}" data-nav="contact">${txt('List with us','اعرض عقارك')}</a></div><div><b>${txt('Speak to an advisor','تواصل مع مستشار')}</b><p>${esc(state.settings.address||'United Arab Emirates')}</p><a href="mailto:${esc(state.settings.email||'info@example.com')}">${ico('mail',15)} ${esc(state.settings.email||'info@example.com')}</a><a href="${route('contact')}" data-nav="contact">${txt('Send an inquiry','إرسال استفسار')} ${ico('arrow',15)}</a><small class="demo-disclosure">${txt('Portfolio imagery and property listings are demonstration content until replaced by the company.','الصور والعقارات المعروضة لأغراض المعاينة حتى استبدالها بالبيانات الفعلية.')}</small></div></div><div class="container footer-bottom"><span>© ${new Date().getFullYear()} AL HASM PREMIER PROPERTIES. ${txt('All rights reserved.','جميع الحقوق محفوظة.')}</span><span>${txt('Designed for extraordinary spaces','تصميم يليق بالأماكن الاستثنائية')} <a href="${adminLink}">${txt('Administration','الإدارة')}</a></span></div></footer>`}
